{"command":"cat << 'EOF' > src/style.rs
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Color {
    Ansi(u8),
    Ansi256(u8),
    Rgb(u8, u8, u8),
    Syntax,
    Normal,
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Style {
    pub is_omit: bool,
    pub is_raw: bool,
    pub is_box: bool,
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub dim: bool,
    pub italic: bool,
    pub underline: bool,
    pub overline: bool,
    pub strike: bool,
    pub reverse: bool,
}

impl Style {
    pub fn parse(s: &str, is_dark: bool) -> Self {
        let mut style = Style::default();
        let tokens: Vec<&str> = s.split_whitespace().collect();
        let mut color_tokens = Vec::new();

        for token in tokens {
            let token_lower = token.to_lowercase();
            match token_lower.as_str() {
                "omit" => style.is_omit = true,
                "raw" => style.is_raw = true,
                "box" => style.is_box = true,
                "bold" => style.bold = true,
                "dim" | "faint" => style.dim = true,
                "italic" => style.italic = true,
                "ul" | "underline" => style.underline = true,
                "ol" | "overline" => style.overline = true,
                "strike" | "strikethrough" => style.strike = true,
                "reverse" | "reversed" => style.reverse = true,
                _ => {
                    color_tokens.push(token);
                }
            }
        }

        if color_tokens.len() == 1 {
            style.fg = parse_color(color_tokens[0], is_dark, true);
        } else if color_tokens.len() >= 2 {
            style.fg = parse_color(color_tokens[0], is_dark, true);
            style.bg = parse_color(color_tokens[1], is_dark, false);
        }

        style
    }

    pub fn ansi_prefix(&self) -> String {
        if self.is_omit || self.is_raw {
            return String::new();
        }
        let mut codes = Vec::new();

        if self.bold { codes.push("1".to_string()); }
        if self.dim { codes.push("2".to_string()); }
        if self.italic { codes.push("3".to_string()); }
        if self.underline { codes.push("4".to_string()); }
        if self.reverse { codes.push("7".to_string()); }
        if self.strike { codes.push("9".to_string()); }
        if self.overline { codes.push("53".to_string()); }

        if let Some(ref fg) = self.fg {
            match fg {
                Color::Ansi(n) => {
                    if *n < 8 {
                        codes.push(format!("{}", 30 + n));
                    } else if *n < 16 {
                        codes.push(format!("{}", 90 + (n - 8)));
                    } else {
                        codes.push(format!("38;5;{}", n));
                    }
                }
                Color::Ansi256(n) => codes.push(format!("38;5;{}", n)),
                Color::Rgb(r, g, b) => codes.push(format!("38;2;{};{};{}", r, g, b)),
                Color::Syntax | Color::Normal => {}
            }
        }

        if let Some(ref bg) = self.bg {
            match bg {
                Color::Ansi(n) => {
                    if *n < 8 {
                        codes.push(format!("{}", 40 + n));
                    } else if *n < 16 {
                        codes.push(format!("{}", 100 + (n - 8)));
                    } else {
                        codes.push(format!("48;5;{}", n));
                    }
                }
                Color::Ansi256(n) => codes.push(format!("48;5;{}", n)),
                Color::Rgb(r, g, b) => codes.push(format!("48;2;{};{};{}", r, g, b)),
                Color::Syntax | Color::Normal => {}
            }
        }

        if codes.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", codes.join(";"))
        }
    }

    pub fn ansi_suffix(&self) -> String {
        if self.is_omit || self.is_raw || (self.ansi_prefix().is_empty()) {
            String::new()
        } else {
            "\x1b[0m".to_string()
        }
    }

    pub fn apply(&self, text: &str) -> String {
        let prefix = self.ansi_prefix();
        if prefix.is_empty() {
            text.to_string()
        } else {
            format!("{}{}\x1b[0m", prefix, text)
        }
    }
}

fn parse_color(s: &str, is_dark: bool, _is_fg: bool) -> Option<Color> {
    let s_lower = s.to_lowercase();
    match s_lower.as_str() {
        "syntax" => Some(Color::Syntax),
        "normal" => Some(Color::Normal),
        "auto" => {
            if is_dark {
                Some(Color::Ansi256(52))
            } else {
                Some(Color::Ansi256(224))
            }
        }
        "black" => Some(Color::Ansi(0)),
        "red" => Some(Color::Ansi(1)),
        "green" => Some(Color::Ansi(2)),
        "yellow" => Some(Color::Ansi(3)),
        "blue" => Some(Color::Ansi(4)),
        "magenta" | "purple" => Some(Color::Ansi(5)),
        "cyan" => Some(Color::Ansi(6)),
        "white" => Some(Color::Ansi(7)),
        "brightblack" | "gray" | "grey" => Some(Color::Ansi(8)),
        "brightred" => Some(Color::Ansi(9)),
        "brightgreen" => Some(Color::Ansi(10)),
        "brightyellow" => Some(Color::Ansi(11)),
        "brightblue" => Some(Color::Ansi(12)),
        "brightmagenta" | "brightpurple" => Some(Color::Ansi(13)),
        "brightcyan" => Some(Color::Ansi(14)),
        "brightwhite" => Some(Color::Ansi(15)),
        _ => {
            if let Ok(n) = s.parse::<u8>() {
                if n < 16 {
                    Some(Color::Ansi(n))
                } else {
                    Some(Color::Ansi256(n))
                }
            } else if s.starts_with('#') {
                if let Ok(c) = csscolorparser::parse(s) {
                    let [r, g, b, _] = c.to_rgba8();
                    Some(Color::Rgb(r, g, b))
                } else {
                    None
                }
            } else if let Ok(c) = csscolorparser::parse(s) {
                let [r, g, b, _] = c.to_rgba8();
                Some(Color::Rgb(r, g, b))
            } else {
                None
            }
        }
    }
}
EOF"}

