impl Config {
    pub fn from_matches(matches: &clap::ArgMatches) -> Self {
        let no_gitconfig = matches.get_flag("no-gitconfig");
        let config_path_arg = matches.get_one::<String>("config").cloned().unwrap_or_default();

        let is_dark = if matches.get_flag("light") {
            false
        } else if matches.get_flag("dark") {
            true
        } else {
            true
        };

        let mut git_config_map = HashMap::new();
        let mut git_features_map: HashMap<String, HashMap<String, String>> = HashMap::new();

        if !no_gitconfig {
