fn get_gitconfig_files(config_path_arg: &str) -> Vec<PathBuf> {
    let mut files = Vec::new();
    if !config_path_arg.is_empty() {
        files.push(PathBuf::from(config_path_arg));
        return files;
    }

    if let Ok(global_config) = std::env::var("GIT_CONFIG_GLOBAL") {
        if !global_config.is_empty() {
            files.push(PathBuf::from(global_config));
            return files;
        }
    }

    if let Some(home) = dirs::home_dir() {
        let global_gitconfig = home.join(".gitconfig");
        if global_gitconfig.exists() {
            files.push(global_gitconfig);
        }
    }

    let repo_gitconfig = PathBuf::from(".git/config");
    if repo_gitconfig.exists() {
        files.push(repo_gitconfig);
    }

    files
}

fn parse_gitconfig_file(
    path: &Path,
    git_config_map: &mut HashMap<String, String>,
    git_features_map: &mut HashMap<String, HashMap<String, String>>,
) {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return,
    };

    let mut current_section = "";
    let mut current_feature = "";

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with(';') {
            continue;
        }

        if line.starts_with('[') && line.ends_with(']') {
            let sec = line[1..line.len() - 1].trim();
            if sec.starts_with("delta \"") && sec.ends_with('"') {
                current_section = "delta_feature";
                current_feature = &sec[7..sec.len() - 1];
            } else if sec == "delta" {
                current_section = "delta";
                current_feature = "";
            } else if sec == "include" {
                current_section = "include";
                current_feature = "";
            } else {
                current_section = "";
                current_feature = "";
            }
            continue;
        }

        if let Some((k, v)) = line.split_once('=') {
            let key = k.trim().to_string();
            let mut val = v.trim().to_string();
            if (val.starts_with('"') && val.ends_with('"')) || (val.starts_with('\'') && val.ends_with('\'')) {
                if val.len() >= 2 {
                    val = val[1..val.len() - 1].to_string();
                }
            }

            if current_section == "delta" {
                git_config_map.insert(key, val);
            } else if current_section == "delta_feature" && !current_feature.is_empty() {
                git_features_map.entry(current_feature.to_string())
                    .or_default()
                    .insert(key, val);
            } else if current_section == "include" && key == "path" {
                let inc_path = PathBuf::from(val);
                let full_path = if inc_path.is_absolute() {
                    inc_path
                } else if let Some(parent) = path.parent() {
                    parent.join(inc_path)
                } else {
                    inc_path
                };
                parse_gitconfig_file(&full_path, git_config_map, git_features_map);
            }
        }
    }
}

fn terminal_width() -> usize {
    if let Ok((w, _)) = crossterm::terminal::size() {
        w as usize
    } else {
        80
    }
}
