pub fn format_decoration(text: &str, style_str: &str, deco_style_str: &str, config: &Config) -> Vec<String> {
    let style = Style::parse(style_str, config.is_dark);
    let deco_style = Style::parse(deco_style_str, config.is_dark);

    if deco_style.is_omit || style.is_omit {
        return vec![];
    }

    let raw_text = text;
    let text_len = unicode_width::UnicodeWidthStr::width(raw_text);
    let full_width = config.width.max(text_len);

    let mut lines = Vec::new();

    if deco_style.is_box {
        let box_width = text_len + 2;
        let top = format!("{}┐", "─".repeat(box_width.saturating_sub(1)));
        let mid = format!("{} │", style.apply(raw_text));
        let bot = format!("{}┘", "─".repeat(box_width.saturating_sub(1)));

        lines.push(deco_style.apply(&top));
        lines.push(mid);
        lines.push(deco_style.apply(&bot));
    } else {
        if deco_style.overline {
            let rule = "─".repeat(full_width);
            lines.push(deco_style.apply(&rule));
        }
        lines.push(style.apply(raw_text));
        if deco_style.underline {
            let rule = "─".repeat(full_width);
            lines.push(deco_style.apply(&rule));
        }
    }

    lines
}

