            "Cargo.lock" | "Cargo.toml" => "toml",
            "Makefile" | "makefile" => "sh",
            "Dockerfile" => "sh",
            _ => "txt",
        }
    }
}

pub fn highlight_line(line: &str, lang: &str, is_dark: bool) -> String {
    if lang == "txt" || line.is_empty() {
        return if is_dark {
            format!("\x1b[38;5;231m{}\x1b[0m", line)
        } else {
            format!("\x1b[38;5;16m{}\x1b[0m", line)
        };
    }

    let kw_color = if is_dark { "\x1b[38;5;203m" } else { "\x1b[38;5;160m" };
    let fn_color = if is_dark { "\x1b[38;5;149m" } else { "\x1b[38;5;26m" };
    let str_color = if is_dark { "\x1b[38;5;186m" } else { "\x1b[38;5;28m" };
    let num_color = if is_dark { "\x1b[38;5;141m" } else { "\x1b[38;5;166m" };
    let comment_color = if is_dark { "\x1b[38;5;242m" } else { "\x1b[38;5;244m" };
    let plain_color = if is_dark { "\x1b[38;5;231m" } else { "\x1b[38;5;16m" };

    let line_trim = line.trim();
    if line_trim.starts_with("//") || line_trim.starts_with('#') || line_trim.starts_with("/*") {
        return format!("{}{}\x1b[0m", comment_color, line);
    }

    let keywords: &[&str] = match lang {
        "rs" => &["fn", "let", "mut", "pub", "struct", "enum", "impl", "use", "mod", "match", "if", "else", "return", "for", "while", "loop", "self", "trait", "type", "const", "static", "async", "await"],
        "py" => &["def", "class", "import", "from", "as", "return", "if", "elif", "else", "for", "while", "try", "except", "with", "raise", "async", "await", "lambda", "in", "is", "not", "and", "or", "True", "False", "None"],
        "js" | "ts" => &["function", "const", "let", "var", "return", "if", "else", "for", "while", "switch", "case", "import", "export", "default", "from", "class", "async", "await", "new", "this"],
        "c" | "cpp" => &["int", "char", "float", "double", "void", "struct", "class", "public", "private", "protected", "return", "if", "else", "for", "while", "switch", "case", "include", "define", "const", "static"],
        "sh" => &["if", "then", "else", "fi", "for", "in", "do", "done", "while", "case", "esac", "function", "export", "local", "echo"],
        _ => &[],
    };

    let mut result = String::new();
    let re = Regex::new(r#""[^"]*"|'[^']*'|\b[0-9]+\.?[0-9]*\b|\b[a-zA-Z_][a-zA-Z0-9_]*\b|[^\s\w]+"#).unwrap();

    let mut last_idx = 0;
    for cap in re.find_iter(line) {
        if cap.start() > last_idx {
            result.push_str(plain_color);
            result.push_str(&line[last_idx..cap.start()]);
        }
        let token = cap.as_str();

        if (token.starts_with('"') && token.ends_with('"')) || (token.starts_with('\'') && token.ends_with('\'')) {
            result.push_str(str_color);
            result.push_str(token);
        } else if token.chars().next().map_or(false, |c| c.is_ascii_digit()) {
            result.push_str(num_color);
            result.push_str(token);
        } else if keywords.contains(&token) {
            result.push_str(kw_color);
            result.push_str(token);
        } else if line[cap.end()..].starts_with('(') {
            result.push_str(fn_color);
            result.push_str(token);
        } else {
            result.push_str(plain_color);
            result.push_str(token);
        }

        last_idx = cap.end();
    }

    if last_idx < line.len() {
        result.push_str(plain_color);
        result.push_str(&line[last_idx..]);
    }

    result.push_str("\x1b[0m");
    result
}
EOF"}

