        if line.starts_with("diff --git ") {
            let mut out = self.flush_hunk_lines();
            let parts: Vec<&str> = line.split_whitespace().collect();
            let file1 = parts.get(2).map(|s| s.trim_start_matches("a/")).unwrap_or("file");
            let file2 = parts.get(3).map(|s| s.trim_start_matches("b/")).unwrap_or("file");
            self.lang = detect_lang(file2);

            let header_text = if file1 == file2 {
                file1.to_string()
            } else {
                format!("{} {} {}", file1, self.config.right_arrow, file2)
            };

            let dec_lines = format_decoration(
                &header_text,
                &self.config.file_style,
                &self.config.file_decoration_style,
                self.config,
            );
            out.extend(dec_lines);
            return out;
        }

        if line.starts_with("--- ") || line.starts_with("+++ ") || line.starts_with("index ") {
            if self.config.color_only {
                let st = Style::parse("blue", self.config.is_dark);
                return vec![st.apply(line)];
