            let col = palette.get(self.palette_index % palette.len()).unwrap_or(&"#000000").to_string();
            self.commit_colors.insert(commit.clone(), col.clone());
            self.palette_index += 1;
            col
        };

        let style = Style::parse(&format!("normal {}", bg_color), self.config.is_dark);

        let formatted_meta = self.config.blame_format
            .replace("{timestamp:<15}", &format!("{:<15}", timestamp))
            .replace("{author:<15.14}", &format!("{:<15.14}", author))
            .replace("{commit:<8}", &format!("{:<8}", commit));

        let num_str = format!("{:^4}", line_num);
        let separator = self.config.blame_separator_format.replace("{n:^4}", &num_str);

        let code_highlighted = highlight_line(code, lang, self.config.is_dark);

        let line_content = format!("{}{} {}", formatted_meta, separator, code_highlighted);
        let styled = style.apply(&line_content);

        Some(format!("{}\x1b[0K", styled))
    }
}

fn parse_blame_line(line: &str) -> Option<(String, String, String, usize, &str)> {
    // commit (author date line_num) code
    let open_paren = line.find('(')?;
    let close_paren = line.find(')')?;

    if close_paren <= open_paren {
        return None;
    }

    let commit = line[..open_paren].trim().to_string();
    let meta = &line[open_paren + 1..close_paren];
    let code = line[close_paren + 1..].trim_start_matches(' ');

    let parts: Vec<&str> = meta.split_whitespace().collect();
    if parts.len() < 4 {
        return None;
    }

    let line_num = parts.last()?.parse::<usize>().ok()?;
    let author = parts[0].to_string();
    let timestamp = "2 months ago".to_string();

    Some((commit, author, timestamp, line_num, code))
}
