{"command":"cat << 'EOF' > src/pager.rs
use std::process::{Command, Child, Stdio};
use std::io::{self, Write};
use crate::config::Config;

pub enum OutputTarget {
    Stdout(io::Stdout),
    Pager(Child),
}

impl OutputTarget {
    pub fn new(config: &Config) -> Self {
        if config.paging == "never" || !is_stdout_tty() {
            return OutputTarget::Stdout(io::stdout());
        }

        let pager_cmd = if !config.pager.is_empty() && config.pager != "none" {
            config.pager.clone()
        } else if let Ok(p) = std::env::var("DELTA_PAGER") {
            p
        } else if let Ok(p) = std::env::var("BAT_PAGER") {
            p
        } else if let Ok(p) = std::env::var("PAGER") {
            p
        } else {
            "less -R".to_string()
        };

        if pager_cmd == "none" || pager_cmd.is_empty() {
            return OutputTarget::Stdout(io::stdout());
        }

        let parts: Vec<&str> = pager_cmd.split_whitespace().collect();
        if parts.is_empty() {
            return OutputTarget::Stdout(io::stdout());
        }

        let mut cmd = Command::new(parts[0]);
        if parts.len() > 1 {
            cmd.args(&parts[1..]);
        }

        cmd.stdin(Stdio::piped());

        match cmd.spawn() {
            Ok(child) => OutputTarget::Pager(child),
            Err(_) => OutputTarget::Stdout(io::stdout()),
        }
    }

    pub fn write_line(&mut self, line: &str) -> io::Result<()> {
        match self {
            OutputTarget::Stdout(out) => {
                let mut handle = out.lock();
                writeln!(handle, "{}", line)?;
            }
            OutputTarget::Pager(child) => {
                if let Some(ref mut stdin) = child.stdin {
                    writeln!(stdin, "{}", line)?;
                }
            }
        }
        Ok(())
    }

    pub fn finish(mut self) {
        if let OutputTarget::Pager(mut child) = self {
            drop(child.stdin.take());
            let _ = child.wait();
        }
    }
}

fn is_stdout_tty() -> bool {
    crossterm::tty::IsTty::is_tty(&io::stdout())
}
EOF"}

