use crate::config::Config;
use crate::style::Style;
use crate::draw::{format_decoration, format_hunk_header};
use crate::syntax::{detect_lang, highlight_line};
use difflib::sequencematcher::SequenceMatcher;

#[derive(Debug, PartialEq)]
pub enum DiffLineType {
    Commit(String),
    DiffHeader(String, String, String), // action, file1, file2
    HunkHeader {
        old_start: usize,
        old_count: usize,
        new_start: usize,
        new_count: usize,
        code: String,
    },
    Minus(String),
    Plus(String),
    Zero(String),
    Other(String),
}

pub struct DiffProcessor<'a> {
    config: &'a Config,
    lang: &'static str,
    old_line_num: usize,
    new_line_num: usize,
    pending_minus: Vec<String>,
    pending_plus: Vec<String>,
}

impl<'a> DiffProcessor<'a> {
    pub fn new(config: &'a Config) -> Self {
        Self {
            config,
            lang: "txt",
            old_line_num: 0,
            new_line_num: 0,
            pending_minus: Vec::new(),
            pending_plus: Vec::new(),
        }
    }

    pub fn process_line(&mut self, line: &str) -> Vec<String> {
        if self.config.raw {
            return vec![line.to_string()];
        }

        if line.starts_with("commit ") {
            let mut out = self.flush_hunk_lines();
            out.push(line.to_string());
            return out;
        }

        if line.starts_with("diff --git ") {
            let mut out = self.flush_hunk_lines();
            let parts: Vec<&str> = line.split_whitespace().collect();
            let file1 = parts.get(2).map(|s| s.trim_start_matches("a/")).unwrap_or("file");
            let file2 = parts.get(3).map(|s| s.trim_start_matches("b/")).unwrap_or("file");
            self.lang = detect_lang(file2);

            let header_text = if file1 == file2 {
                file1.to_string()
            } else {
                format!("{} {} {}", file1, self.config.right_arrow, file2)
            };

            let dec_lines = format_decoration(
                &header_text,
                &self.config.file_style,
                &self.config.file_decoration_style,
                self.config,
            );
            out.extend(dec_lines);
            return out;
        }

        if line.starts_with("--- ") || line.starts_with("+++ ") || line.starts_with("index ") {
            if self.config.color_only {
                let st = Style::parse("blue", self.config.is_dark);
                return vec![st.apply(line)];
            }
            return vec![];
        }

        if line.starts_with("@@ ") {
            let mut out = self.flush_hunk_lines();
            if let Some((old_start, _old_count, new_start, _new_count, code)) = parse_hunk_header(line) {
                self.old_line_num = old_start;
                self.new_line_num = new_start;
                let h_lines = format_hunk_header(old_start, new_start, &code, self.config);
                out.extend(h_lines);
            } else {
                out.push(line.to_string());
            }
            return out;
        }

        if line.starts_with('-') && !line.starts_with("--- ") {
            self.pending_minus.push(line.to_string());
            return vec![];
        }

        if line.starts_with('+') && !line.starts_with("+++ ") {
            self.pending_plus.push(line.to_string());
            return vec![];
        }

        let mut out = self.flush_hunk_lines();

        if line.starts_with(' ') {
            let text = &line[1..];
            let line_out = self.format_zero_line(text);
            self.old_line_num += 1;
            self.new_line_num += 1;
            out.push(line_out);
        } else {
            out.push(line.to_string());
        }

        out
    }

    pub fn finish(&mut self) -> Vec<String> {
        self.flush_hunk_lines()
    }

    fn flush_hunk_lines(&mut self) -> Vec<String> {
        let mut out = Vec::new();
        if self.pending_minus.is_empty() && self.pending_plus.is_empty() {
            return out;
        }

        let minus_lines = std::mem::take(&mut self.pending_minus);
        let plus_lines = std::mem::take(&mut self.pending_plus);

        let max_len = minus_lines.len().max(plus_lines.len());
        for i in 0..max_len {
            let m_opt = minus_lines.get(i);
            let p_opt = plus_lines.get(i);

            if let (Some(m_line), Some(p_line)) = (m_opt, p_opt) {
                let m_text = if self.config.keep_plus_minus_markers { m_line.as_str() } else { &m_line[1..] };
                let p_text = if self.config.keep_plus_minus_markers { p_line.as_str() } else { &p_line[1..] };

                let (m_rendered, p_rendered) = self.format_word_diff(m_text, p_text);
                out.push(m_rendered);
                out.push(p_rendered);
                self.old_line_num += 1;
                self.new_line_num += 1;
            } else if let Some(m_line) = m_opt {
                let m_text = if self.config.keep_plus_minus_markers { m_line.as_str() } else { &m_line[1..] };
                let m_rendered = self.format_minus_line(m_text);
                out.push(m_rendered);
                self.old_line_num += 1;
            } else if let Some(p_line) = p_opt {
                let p_text = if self.config.keep_plus_minus_markers { p_line.as_str() } else { &p_line[1..] };
                let p_rendered = self.format_plus_line(p_text);
                out.push(p_rendered);
                self.new_line_num += 1;
            }
        }

        out
    }

    fn format_zero_line(&self, text: &str) -> String {
        let text_styled = highlight_line(text, self.lang, self.config.is_dark);
        if self.config.line_numbers {
            let left_num = format!("{:^4}", self.old_line_num);
            let right_num = format!("{:^4}", self.new_line_num);
            let num_zero_style = Style::parse(&self.config.line_numbers_zero_style, self.config.is_dark);
            let border_style = Style::parse(&self.config.line_numbers_left_style, self.config.is_dark);

            format!(
                "{}{}{}{}{}{}",
                border_style.apply(""),
                num_zero_style.apply(&left_num),
                border_style.apply("⋮"),
                num_zero_style.apply(&right_num),
                border_style.apply("│"),
                text_styled
            )
        } else {
            text_styled
        }
    }

    fn format_minus_line(&self, text: &str) -> String {
        let minus_style = Style::parse(&self.config.minus_style, self.config.is_dark);
        let text_styled = minus_style.apply(text);

        let line_content = if self.config.line_numbers {
            let left_num = format!("{:^4}", self.old_line_num);
            let num_minus_style = Style::parse(&self.config.line_numbers_minus_style, self.config.is_dark);
            let border_style = Style::parse(&self.config.line_numbers_left_style, self.config.is_dark);

            format!(
                "{}{}{}{}{}",
                num_minus_style.apply(&left_num),
                border_style.apply("⋮"),
                num_minus_style.apply("    "),
                border_style.apply("│"),
                text_styled
            )
        } else {
            text_styled
        };

        format!("{}\x1b[0K", line_content)
    }

    fn format_plus_line(&self, text: &str) -> String {
        let plus_style = Style::parse(&self.config.plus_style, self.config.is_dark);
        let text_highlighted = highlight_line(text, self.lang, self.config.is_dark);
        let text_styled = plus_style.apply(&text_highlighted);

        let line_content = if self.config.line_numbers {
            let right_num = format!("{:^4}", self.new_line_num);
            let num_plus_style = Style::parse(&self.config.line_numbers_plus_style, self.config.is_dark);
            let border_style = Style::parse(&self.config.line_numbers_right_style, self.config.is_dark);

            format!(
                "{}{}{}{}{}",
                num_plus_style.apply("    "),
                border_style.apply("⋮"),
                num_plus_style.apply(&right_num),
                border_style.apply("│"),
                text_styled
            )
        } else {
            text_styled
        };

        format!("{}\x1b[0K", line_content)
    }

    fn format_word_diff(&self, m_text: &str, p_text: &str) -> (String, String) {
        let m_tokens = tokenize_words(m_text);
        let p_tokens = tokenize_words(p_text);

        let matcher = SequenceMatcher::new(&m_tokens, &p_tokens);
        let opcodes = matcher.get_opcodes();

        let minus_style = Style::parse(&self.config.minus_style, self.config.is_dark);
        let minus_emph_style = Style::parse(&self.config.minus_emph_style, self.config.is_dark);

        let plus_style = Style::parse(&self.config.plus_style, self.config.is_dark);
        let plus_emph_style = Style::parse(&self.config.plus_emph_style, self.config.is_dark);

        let mut m_out = String::new();
        let mut p_out = String::new();

        for op in opcodes {
            match op.tag.as_str() {
                "equal" => {
                    let m_chunk = m_tokens[op.first_start..op.first_end].join("");
                    let p_chunk = p_tokens[op.second_start..op.second_end].join("");
                    m_out.push_str(&minus_style.apply(&m_chunk));
                    p_out.push_str(&plus_style.apply(&highlight_line(&p_chunk, self.lang, self.config.is_dark)));
                }
                "replace" | "delete" | "insert" => {
                    let m_chunk = m_tokens[op.first_start..op.first_end].join("");
                    let p_chunk = p_tokens[op.second_start..op.second_end].join("");
                    if !m_chunk.is_empty() {
                        m_out.push_str(&minus_emph_style.apply(&m_chunk));
                    }
                    if !p_chunk.is_empty() {
                        p_out.push_str(&plus_emph_style.apply(&highlight_line(&p_chunk, self.lang, self.config.is_dark)));
                    }
                }
                _ => {}
            }
        }

        let m_final = if self.config.line_numbers {
            let left_num = format!("{:^4}", self.old_line_num);
            let num_minus_style = Style::parse(&self.config.line_numbers_minus_style, self.config.is_dark);
            let border_style = Style::parse(&self.config.line_numbers_left_style, self.config.is_dark);
            format!(
                "{}{}{}{}{}\x1b[0K",
                num_minus_style.apply(&left_num),
                border_style.apply("⋮"),
                num_minus_style.apply("    "),
                border_style.apply("│"),
                m_out
            )
        } else {
            format!("{}\x1b[0K", m_out)
        };

        let p_final = if self.config.line_numbers {
            let right_num = format!("{:^4}", self.new_line_num);
            let num_plus_style = Style::parse(&self.config.line_numbers_plus_style, self.config.is_dark);
            let border_style = Style::parse(&self.config.line_numbers_right_style, self.config.is_dark);
            format!(
                "{}{}{}{}{}\x1b[0K",
                num_plus_style.apply("    "),
                border_style.apply("⋮"),
                num_plus_style.apply(&right_num),
                border_style.apply("│"),
                p_out
            )
        } else {
            format!("{}\x1b[0K", p_out)
        };

        (m_final, p_final)
    }
}

fn parse_hunk_header(line: &str) -> Option<(usize, usize, usize, usize, String)> {
    // @@ -old_start,old_count +new_start,new_count @@ [code]
    let rest = line.strip_prefix("@@ ")?;
    let (header, code) = rest.split_once(" @@")?;

    let parts: Vec<&str> = header.split_whitespace().collect();
    if parts.len() < 2 {
        return None;
    }

    let old_part = parts[0].strip_prefix('-')?;
    let new_part = parts[1].strip_prefix('+')?;

    let (old_start, old_count) = parse_range(old_part);
    let (new_start, new_count) = parse_range(new_part);

    Some((old_start, old_count, new_start, new_count, code.trim().to_string()))
}

fn parse_range(s: &str) -> (usize, usize) {
    if let Some((start, count)) = s.split_once(',') {
        (start.parse().unwrap_or(1), count.parse().unwrap_or(1))
    } else {
        (s.parse().unwrap_or(1), 1)
    }
}

fn tokenize_words(s: &str) -> Vec<String> {
    let re = regex::Regex::new(r"\w+|[^\w]+").unwrap();
    re.find_iter(s).map(|m| m.as_str().to_string()).collect()
}
EOF"}

