cat << 'EOF' > src/main.rs
mod cli;
mod style;
mod config;
mod draw;
mod syntax;
mod diff;
mod blame;
mod grep;
mod pager;

use std::io::{self, BufRead};
use std::process::{Command, Stdio, exit};
use clap_complete::{generate, Shell};

fn main() {
    let mut command = cli::build_cli();
    let matches = command.clone().get_matches();

    if matches.get_flag("list-languages") {
        syntax::list_languages();
        return;
    }

    if matches.get_flag("list-syntax-themes") {
        syntax::list_syntax_themes();
        return;
    }

    if let Some(shell_str) = matches.get_one::<String>("generate-completion") {
        let shell = match shell_str.to_lowercase().as_str() {
            "bash" => Shell::Bash,
            "zsh" => Shell::Zsh,
            "fish" => Shell::Fish,
            "powershell" => Shell::PowerShell,
            "elvish" => Shell::Elvish,
            _ => Shell::Bash,
        };
        generate(shell, &mut command, "delta", &mut io::stdout());
        return;
    }

    let config = config::Config::from_matches(&matches);

    if matches.get_flag("show-config") {
        config.show_config();
        return;
    }

    if matches.get_flag("show-colors") {
        show_colors(&config);
        return;
    }

    if matches.get_flag("show-syntax-themes") {
        show_syntax_themes(&config);
        return;
    }

    if matches.get_flag("show-themes") {
        show_themes(&config);
        return;
    }

    let file1 = matches.get_one::<String>("MINUS_FILE");
    let file2 = matches.get_one::<String>("PLUS_FILE");

    if let (Some(f1), Some(f2)) = (file1, file2) {
        let exit_code = process_two_files(f1, f2, &config);
        exit(exit_code);
    }

    // Stdin mode
    process_stdin(&config);
}

fn process_two_files(f1: &str, f2: &str, config: &config::Config) -> i32 {
    let mut diff_cmd = Command::new("diff");
    diff_cmd.arg("-u");

    if !config.diff_args.is_empty() {
        for arg in config.diff_args.split_whitespace() {
            diff_cmd.arg(arg);
        }
    }

    diff_cmd.arg(f1).arg(f2);
    diff_cmd.stdout(Stdio::piped());

    let mut child = match diff_cmd.spawn() {
        Ok(c) => c,
        Err(_) => return 2,
    };

    let mut output = pager::OutputTarget::new(config);
    let mut processor = diff::DiffProcessor::new(config);

    if let Some(stdout) = child.stdout.take() {
        let reader = io::BufReader::new(stdout);
        for line_res in reader.lines() {
            if let Ok(line) = line_res {
                let formatted = processor.process_line(&line);
                for l in formatted {
                    let _ = output.write_line(&l);
                }
            }
        }
    }

    let remaining = processor.finish();
    for l in remaining {
        let _ = output.write_line(&l);
    }

    output.finish();

    let status = child.wait().ok();
    status.and_then(|s| s.code()).unwrap_or(1)
}

fn process_stdin(config: &config::Config) {
    let stdin = io::stdin();
    let reader = stdin.lock();

    let mut output = pager::OutputTarget::new(config);
    let mut diff_processor = diff::DiffProcessor::new(config);
    let mut blame_processor = blame::BlameProcessor::new(config);

    for line_res in reader.lines() {
        let line = match line_res {
            Ok(l) => l,
            Err(_) => break,
        };

        if let Some(blame_out) = blame_processor.process_line(&line, "txt") {
            let _ = output.write_line(&blame_out);
        } else if let Some(grep_out) = grep::process_grep_line(&line, config) {
            let _ = output.write_line(&grep_out);
        } else {
            let formatted = diff_processor.process_line(&line);
            for l in formatted {
                let _ = output.write_line(&l);
            }
        }
    }

    let remaining = diff_processor.finish();
    for l in remaining {
        let _ = output.write_line(&l);
    }

    output.finish();
}

fn show_colors(config: &config::Config) {
    let sample = "export function color(): string { return \"cadetblue\" }\nexport function hex(): string { return \"#5f9ea0\" }";
    let mut output = pager::OutputTarget::new(config);
    let _ = output.write_line("\n\x1b[1mBlue\x1b[0m\n");
    for line in sample.lines() {
        let _ = output.write_line(&syntax::highlight_line(line, "ts", config.is_dark));
    }
    output.finish();
}

fn show_syntax_themes(config: &config::Config) {
    let sample_diff = "\
diff --git a/example.rs b/example.rs
index 1234567..89abcde 100644
--- a/example.rs
+++ b/example.rs
@@ -1,5 +1,5 @@
-// Output the square of a number.
-fn print_square(num: f64) {
    let result = f64::powf(num, 2.0);
    println!(\"The square of {:.2} is {:.2}.\", num, result);
+// Output the cube of a number.
+fn print_cube(num: f64) {
    let result = f64::powf(num, 3.0);
    println!(\"The cube of {:.2} is {:.2}.\", num, result);
";

    let mut output = pager::OutputTarget::new(config);
    let themes = ["1337", "Coldark-Cold", "DarkNeon", "Dracula", "GitHub", "Monokai Extended", "Nord", "OneHalfDark", "Solarized (dark)", "TwoDark"];

    for theme in themes {
        let _ = output.write_line(&format!("\n\nSyntax theme: \x1b[1m{}\x1b[0m\n\n", theme));
        let mut diff_processor = diff::DiffProcessor::new(config);
        for line in sample_diff.lines() {
            for l in diff_processor.process_line(line) {
                let _ = output.write_line(&l);
            }
        }
        for l in diff_processor.finish() {
            let _ = output.write_line(&l);
        }
    }
    output.finish();
}

fn show_themes(config: &config::Config) {
    let mut output = pager::OutputTarget::new(config);
    let _ = output.write_line("No themes found. Please see https://dandavison.github.io/delta/custom-themes.html.");
    output.finish();
}
