    pub reverse: bool,
}

impl Style {
    pub fn parse(s: &str, is_dark: bool) -> Self {
        let mut style = Style::default();
        let tokens: Vec<&str> = s.split_whitespace().collect();
        let mut color_tokens = Vec::new();

        for token in tokens {
