            match fg {
                Color::Ansi(n) => {
                    if *n < 8 {
                        codes.push(format!("{}", 30 + n));
                    } else if *n < 16 {
                        codes.push(format!("{}", 90 + (n - 8)));
                    } else {
                        codes.push(format!("38;5;{}", n));
                    }
                }
                Color::Ansi256(n) => codes.push(format!("38;5;{}", n)),
                Color::Rgb(r, g, b) => codes.push(format!("38;2;{};{};{}", r, g, b)),
                Color::Syntax | Color::Normal => {}
            }
